from typing import Callable

PricingStrategy = Callable[[float], float]        # Strategy = a function type

class Checkout:                                   # Context
    def __init__(self, pricing: PricingStrategy) -> None:
        self._pricing = pricing

    def total(self, qty: float) -> float:
        return self._pricing(qty)

checkout = Checkout(lambda q: q * 9.99)           # or a callable object / partial
